const intake=$('🧠 Intake').first().json;
const rows=Array.isArray($input.first().json)?$input.first().json:($input.first().json.data||[]);
const state=rows[0]||{ niche:'', style:'', pending_action:null };
const pending=state.pending_action||null;
const sys=`You are the friendly, expert Instagram content manager for a creator. You chat naturally, understand requests, and CONFIRM before creating anything.

Current settings:
- niche: "${state.niche||'(not set)'}"
- visual/video style: "${state.style||'(not set)'}"
- pending action awaiting confirmation: ${pending?JSON.stringify(pending):'(none)'}

Rules:
- If the user wants to set/change the niche or style, intent=set_config and fill set_niche/set_style.
- If the user asks to CREATE something (carousel, video/reel, or image), DO NOT create yet. intent=propose, fill action_type + topic (and slide_count for carousels, script if they pasted one), and write a short reply describing the plan and asking them to reply 'yes' to confirm.
- If the user confirms (yes/ok/go/do it) AND a pending action exists, intent=confirm and echo the pending action_type/topic/script/slide_count.
- If the user cancels, intent=cancel.
- Otherwise intent=chat and just reply helpfully.
- Everything you create must fit the niche and the chosen style. If niche or style is missing and they want to create, ask them to set it first (intent=chat).
Respond with STRICT JSON only.`;
const usr=`User message: "${intake.text}"
Return JSON: {
 "reply": "natural language reply to send back",
 "intent": "set_config | propose | confirm | cancel | chat",
 "set_niche": "", "set_style": "",
 "action_type": "carousel | video | image | none",
 "topic": "", "script": "", "slide_count": 5
}`;
return [{ json:{ chatId:intake.chatId, niche:state.niche||'', style:state.style||'', pending, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.5, max_tokens:700 } } }];

const ctx=$('🧠 Manager Brain Prompt').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const m=(($input.first().json.choices||[{}])[0].message||{}).content||'';const mm=m.match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const pending=ctx.pending||{};
const action_type=(o.action_type&&o.action_type!=='none')?o.action_type:(pending.action_type||'none');
return [{ json:{ chatId:ctx.chatId, niche:ctx.niche, style:ctx.style, reply:o.reply||'Okay!', intent:o.intent||'chat', set_niche:o.set_niche||'', set_style:o.set_style||'', action_type, topic:o.topic||pending.topic||'', script:o.script||pending.script||'', slide_count:Number(o.slide_count||pending.slide_count||5) } }];

const m=$json;
const n=m.slide_count||5;
const sys=`You are an expert Instagram carousel designer for the niche: \"${m.niche}\". Visual style: \"${m.style}\". Design a scroll-stopping ${n}-slide carousel. Respond STRICT JSON only.`;
const usr=`Topic: ${m.topic}\nReturn JSON: {\"slides\":[{\"headline\":\"short on-image text\",\"image_prompt\":\"vivid image description for this slide, vertical 4:5, no text in image\"}],\"caption\":\"engaging IG caption with a hook line, value, CTA and 8-12 hashtags relevant to the niche\"}\nProvide exactly ${n} slides.`;
return [{ json:{ ...m, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1500 } } }];

const m=$('🧩 Prep Action').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const mm=((($input.first().json.choices||[{}])[0].message||{}).content||'').match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const slides=(o.slides||[]).slice(0,m.slide_count||5);
const caption=o.caption||m.topic;
return slides.map((s,i)=>({ json:{ chatId:m.chatId, niche:m.niche, style:m.style, topic:m.topic, job:m.job, caption, idx:i, headline:s.headline||'', image_prompt:s.image_prompt||m.topic } }));

const base=$('🖼️ Carousel: Split Slides').item.json;
const resp=$json;let b64='';
try{ const msg=resp.choices&&resp.choices[0]&&resp.choices[0].message; if(msg&&msg.images&&msg.images[0]){ const u=msg.images[0].image_url?msg.images[0].image_url.url:msg.images[0].url; b64=(u||'').split(',').pop(); } else if(resp.data&&resp.data[0]&&resp.data[0].b64_json){ b64=resp.data[0].b64_json; } }catch(e){}
return [{ json:{ ...base, img_b64:b64 } }];

// run once for all slides
const slides=$('🖼️ Carousel: Split Slides').all().map(i=>i.json);
const hosts=$input.all().map(i=>i.json);
const m=$('🧩 Prep Action').first().json;
const caption=(slides[0]&&slides[0].caption)||m.topic;
const urls=hosts.map(h=>{ try{return h.data.display_url||h.data.url;}catch(e){return '';} }).filter(Boolean);
const profiles=[ $vars.BUFFER_PROFILE_ID_INSTAGRAM ].filter(Boolean);
const parts=[];
profiles.forEach(p=>parts.push('profile_ids[]='+encodeURIComponent(p)));
parts.push('text='+encodeURIComponent(caption));
if(urls[0]) parts.push('media[photo]='+encodeURIComponent(urls[0]));
parts.push('now=true');
return [{ json:{ chatId:m.chatId, job:m.job, niche:m.niche, style:m.style, topic:m.topic, caption, media_urls:urls, bufferBody:parts.join('&') } }];

