const m=$json;
const sys=`You are a Reels scriptwriter AND editor for the niche \"${m.niche}\". Write a high-retention vertical Reel script and self-review it for hook strength and pacing. Visual style for all scenes: \"${m.style}\". Respond STRICT JSON only.`;
let usr;
if(m.script){ usr=`Use THIS script (keep the creator's words, split into 4 scenes, add visuals in the chosen style):\n\"${m.script}\"\nReturn JSON: {\"caption\":\"IG caption + hashtags\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"<=6 words\",\"image_prompt\":\"vertical 9:16 still, no text\",\"motion_prompt\":\"how to animate\"}]}`; }
else { usr=`Topic: ${m.topic}\nWrite a 4-scene Reel: pattern-interrupt hook -> value -> payoff -> CTA. Total 80-120 words.\nReturn JSON: {\"caption\":\"IG caption + hashtags\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"<=6 words\",\"image_prompt\":\"vertical 9:16 still, no text\",\"motion_prompt\":\"how to animate\"}]}`; }
return [{ json:{ ...m, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1400 } } }];

const m=$('🧩 Prep Action').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const mm=((($input.first().json.choices||[{}])[0].message||{}).content||'').match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const scenes=(o.scenes||[]).slice(0,6).map((s,i)=>({ idx:i, narration:s.narration||'', on_screen_text:s.on_screen_text||'', image_prompt:s.image_prompt||m.topic, motion_prompt:s.motion_prompt||'slow cinematic push-in' }));
const caption=o.caption||m.topic;
return scenes.map(s=>({ json:{ chatId:m.chatId, niche:m.niche, style:m.style, topic:m.topic, job:m.job, caption, scene:s } }));

const base=$('🎬 Reel: Split Scenes').item.json;
const resp=$json;let b64='';
try{ const msg=resp.choices&&resp.choices[0]&&resp.choices[0].message; if(msg&&msg.images&&msg.images[0]){ const u=msg.images[0].image_url?msg.images[0].image_url.url:msg.images[0].url; b64=(u||'').split(',').pop(); } else if(resp.data&&resp.data[0]&&resp.data[0].b64_json){ b64=resp.data[0].b64_json; } }catch(e){}
return [{ json:{ ...base, img_b64:b64 } }];

const base=$('🖼️ Scene: Extract').item.json;
let url='';try{url=$json.data.display_url||$json.data.url;}catch(e){}
const body={ model:($vars.OPENROUTER_VIDEO_MODEL||'google/veo-3.1-lite'), prompt:(base.scene.motion_prompt||'slow cinematic push-in')+', '+base.style+', high quality motion', duration:Number($vars.VIDEO_CLIP_SECONDS||4), resolution:'720p', aspect_ratio:'9:16', generate_audio:false, frame_images:[{ type:'image_url', image_url:{ url }, frame_type:'first_frame' }] };
return [{ json:{ ...base, scene_image_url:url, videoBody:body } }];

const preps=$('🧩 Scene: Prep Video').all().map(i=>i.json);
const resps=$input.all().map(i=>i.json);
const m=$('🧩 Prep Action').first().json;
const caption=(preps[0]&&preps[0].caption)||m.topic;
const jobs=resps.map((r,i)=>({ idx:i, jobId:r.id||'', status:r.status||'queued', polling_url:(r.polling_url||('/api/v1/videos/'+(r.id||''))), clip_url:'', narration:(preps[i]&&preps[i].scene.narration)||'', on_screen_text:(preps[i]&&preps[i].scene.on_screen_text)||'' }));
return [{ json:{ chatId:m.chatId, niche:m.niche, style:m.style, topic:m.topic, job:m.job, caption, jobs, attempts:0 } }];

const c=$('📦 Collect Video Jobs').first().json;
const polls=$input.all().map(i=>i.json);
const jobs=c.jobs.map((j,i)=>{ const p=polls[i]||{}; const status=p.status||j.status; let url=j.clip_url; if(status==='completed'){ url=(p.unsigned_urls&&p.unsigned_urls[0])||('https://openrouter.ai/api/v1/videos/'+j.jobId+'/content?index=0'); } return { ...j, status, clip_url:url }; });
const attempts=(c.attempts||0)+1;
const allDone=jobs.every(j=>j.status==='completed'&&j.clip_url);
const anyFailed=jobs.some(j=>['failed','cancelled','expired'].includes(j.status));
return [{ json:{ ...c, jobs, attempts, done: allDone||anyFailed||attempts>=20 } }];

const m=$json;
const KEY=$vars.OPENAI_API_KEY;const OR=$vars.OPENROUTER_API_KEY;
const FONT=$vars.FFMPEG_FONT||'/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf';
const voice=$vars.OPENAI_TTS_VOICE||'nova';
const dir='/tmp/'+m.job;const b64=(s)=>Buffer.from(String(s||''),'utf8').toString('base64');
const L=['set -e','export DIR='+dir,'mkdir -p $DIR','cd $DIR'];const list=[];
(m.jobs||[]).forEach((j,i)=>{
  const auth=j.clip_url.indexOf('openrouter.ai/api')>-1?`-H \"Authorization: Bearer ${OR}\"`:'';
  L.push(`curl -sL ${auth} \"${j.clip_url}\" -o clip_${i}.mp4`);
  const tts=JSON.stringify({model:'tts-1-hd',voice:voice,input:j.narration||m.topic});
  L.push(`echo \"${b64(tts)}\" | base64 -d > tts_${i}.json`);
  L.push(`curl -s https://api.openai.com/v1/audio/speech -H \"Authorization: Bearer ${KEY}\" -H \"Content-Type: application/json\" --data @tts_${i}.json -o voice_${i}.mp3`);
  L.push(`echo \"${b64(j.on_screen_text)}\" | base64 -d > cap_${i}.txt`);
  L.push(`D=$(ffprobe -v error -show_entries format=duration -of csv=p=0 voice_${i}.mp3)`);
  const vf=`scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,drawtext=fontfile=${FONT}:textfile=cap_${i}.txt:fontcolor=white:fontsize=64:box=1:boxcolor=black@0.55:boxborderw=26:x=(w-text_w)/2:y=h-560`;
  L.push(`ffmpeg -y -stream_loop -1 -t $D -i clip_${i}.mp4 -i voice_${i}.mp3 -vf \"${vf}\" -map 0:v -map 1:a -r 30 -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -shortest scene_${i}.mp4`);
  list.push(`file 'scene_${i}.mp4'`);
});
L.push(`printf \"${list.join('\\n')}\\n\" > list.txt`);
L.push(`ffmpeg -y -f concat -safe 0 -i list.txt -c copy ${dir}/final.mp4`);
L.push(`echo DONE ${dir}/final.mp4`);
return [{ json:{ ...m, outPath:dir+'/final.mp4', ffmpegScript:L.join('\n') } }];

const m=$('🎞️ Build FFmpeg Job').first().json;
const publicUrl=`${$vars.SUPABASE_URL}/storage/v1/object/public/videos/${m.job}.mp4`;
const profiles=[ $vars.BUFFER_PROFILE_ID_INSTAGRAM ].filter(Boolean);
const parts=[];profiles.forEach(p=>parts.push('profile_ids[]='+encodeURIComponent(p)));parts.push('text='+encodeURIComponent(m.caption||m.topic));parts.push('media[video]='+encodeURIComponent(publicUrl));parts.push('now=true');
return [{ json:{ chatId:m.chatId, niche:m.niche, style:m.style, topic:m.topic, caption:m.caption, video_url:publicUrl, bufferBody:parts.join('&') } }];

